<div class="page-heading"><p class="eyebrow">OLÁ, <?= e($user['nome']) ?></p><h1>Minha participação</h1><p>Acompanhe seus relatos e as atualizações da moderação.</p><div class="d-flex gap-3"><a href="<?= e(url('/nova')) ?>" class="btn btn-primary">Registrar ocorrência</a><a href="<?= e(url('/perfil')) ?>" class="btn btn-outline-primary">Meu perfil</a></div></div>
<section class="surface"><h2 class="h4">Meus relatos</h2><?php if (!$rows): ?><p>Você ainda não registrou uma ocorrência.</p><?php endif ?><div class="table-responsive"><table class="table"><caption>Até 100 relatos mais recentes da sua conta.</caption><thead><tr><th>Relato</th><th>Situação</th><th>Registro</th><th>Ação</th></tr></thead><tbody><?php foreach ($rows as $r): ?><tr><td><a href="<?= e(url('/ocorrencia',['id'=>$r['id']])) ?>"><?= e($r['titulo']) ?></a></td><td><span class="status status-<?= e($r['status']) ?>"><?= e(status_label($r['status'])) ?></span></td><td><?= e(datebr($r['criado_em'])) ?></td><td><?php if (in_array($r['status'],['PENDENTE','CORRECAO_SOLICITADA'],true)): ?><a href="<?= e(url('/editar',['id'=>$r['id']])) ?>">Editar</a><?php else: ?>Acompanhar<?php endif ?></td></tr><?php endforeach ?></tbody></table></div></section>
<section class="surface mt-4" id="notificacoes"><div class="section-heading"><h2 class="h4">Notificações</h2><form action="<?= e(url('/notificacoes')) ?>" method="post"><?= csrf() ?><button class="btn btn-outline-primary btn-sm">Marcar todas como lidas</button></form></div><?php if (!$notifications): ?><p>Nenhuma atualização por enquanto.</p><?php endif ?><?php foreach ($notifications as $n): ?><article class="notification"><strong><?= $n['lida_em']?'':'Nova · ' ?><?= e($n['titulo']) ?></strong><p><?= e($n['mensagem']) ?></p><a href="<?= e(url('/ocorrencia',['id'=>$n['ocorrencia_id']])) ?>">Consultar relato</a> <small><?= e(datebr($n['criado_em'])) ?></small></article><?php endforeach ?></section>
